// atsHints: "provider:token" pairs to try first ("none" = careers site has no public job API).
// When no hint is given the ingester probes Greenhouse, Ashby and Lever using the slug.

export type SeedCompany = {
  slug: string; name: string; website: string; category: string; hq: string; ownership: string; ticker?: string; maturity: string;
  mp: number; eq: number; cc: number; hints?: string[]; description: string; products: string; buyers: string; ceo?: string; careers?: string; risks?: string; seed?: boolean;
};

const C = (
  slug: string, name: string, website: string, category: string, hq: string, ownership: string, maturity: string,
  scores: [number, number, number], description: string, products: string, buyers: string,
  extra: Partial<SeedCompany> = {},
): SeedCompany => ({ slug, name, website, category, hq, ownership, maturity, mp: scores[0], eq: scores[1], cc: scores[2], description, products, buyers, ...extra });

